-- §175 Erstbestand des Umlagekatalogs 2026.
--
-- WARUM ALS MIGRATION UND NICHT ALS SKRIPT
-- Ein Skript, das jemand ausfuehren muss, wird beim naechsten Aufsetzen
-- vergessen — und dann rechnet eine Anlage still ohne Umlagen. Als Migration
-- laeuft der Erstbestand ueberall mit, ist versioniert und im Diff lesbar.
--
-- WAS „geprueft" HEISST
-- true nur dort, wo die Zahl gegen die Veroeffentlichung der Kasse selbst
-- gehalten wurde (TK, BARMER, DAK, Knappschaft — am 27.09.2026). Der Rest
-- ist uebernommen und traegt seine Quelle, aber keinen Haken. Bei den
-- Pfaendungstabellen waren zwei von acht falsch; aufgefallen ist es nur,
-- weil es dieses Feld gab.
--
-- ON CONFLICT: Ein spaeterer Import ueber `npm run umlagen:import` darf
-- dieselben Zeilen nachziehen, ohne dass hier etwas bricht.

ON CONFLICT ("kasse", "u1Erstattung", "gueltigAb") DO UPDATE SET
  "u1Satz"   = EXCLUDED."u1Satz",
  "u2Satz"   = EXCLUDED."u2Satz",
  "quelle"   = EXCLUDED."quelle",
  "geprueft" = EXCLUDED."geprueft",
  "notiz"    = EXCLUDED."notiz",
  "updatedAt" = CURRENT_TIMESTAMP;
